INSERT INTO feature VALUES('paths-in-products','identity','Paths in products and dependent pairs','identity-types','implemented','notable',NULL,'An identification of pairs is a pair of identifications, fibrewise at a dependent pair. A tuple of paths relates two tuples at a product''s identity in both checkers, so two structures are one along their carrier''s path once each component is carried along it.','core-checker kernel-core','corpus/model/data/sigma-pair.gandr corpus/model/identity/structure-identity.gandr','corpus/model/data/sigma-pair.gandr',NULL);
